// Stage obstacle meshes generated by tools/stage-props.py from Ludo AI
// models of the stage splash paintings. Rerun the tool instead of editing.
// Included by src/host.rs.

/// The generated mesh replacing `kind` for `theme`, if there is one.
fn stage_prop(theme: u8, kind: u8) -> Option<Model> {
    let (vertices, faces): (&[[i16; 3]], &[[u8; 4]]) = match (theme, kind) {
        (0, ROCK) => (&T00_ROCK_VERTICES, &T00_ROCK_FACES),
        (1, ROCK) => (&T01_ROCK_VERTICES, &T01_ROCK_FACES),
        (4, ROCK) => (&T04_ROCK_VERTICES, &T04_ROCK_FACES),
        (5, ROCK) => (&T05_ROCK_VERTICES, &T05_ROCK_FACES),
        (8, ROCK) => (&T08_ROCK_VERTICES, &T08_ROCK_FACES),
        (9, ROCK) => (&T09_ROCK_VERTICES, &T09_ROCK_FACES),
        (10, ROCK) => (&T10_ROCK_VERTICES, &T10_ROCK_FACES),
        (2, BUILDING) => (&T02_BUILDING_VERTICES, &T02_BUILDING_FACES),
        (3, BUILDING) => (&T03_BUILDING_VERTICES, &T03_BUILDING_FACES),
        (6, BUILDING) => (&T06_BUILDING_VERTICES, &T06_BUILDING_FACES),
        (7, BUILDING) => (&T07_BUILDING_VERTICES, &T07_BUILDING_FACES),
        (11, BUILDING) => (&T11_BUILDING_VERTICES, &T11_BUILDING_FACES),
        _ => return None,
    };
    Some((vertices.to_vec(), faces.to_vec()))
}

